import java.io.*; import java.util.*; import java.util.jar.*; import org.objectweb.asm.*; import org.objectweb.asm.tree.*;
public final class CombatDiscovery implements Opcodes {
 static byte[] rd(InputStream in)throws Exception{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)o.write(b,0,n);in.close();return o.toByteArray();} static ClassNode cn(byte[] b){ClassNode c=new ClassNode();new ClassReader(b).accept(c,0);return c;} static List<AbstractInsnNode> real(MethodNode m){List<AbstractInsnNode> r=new ArrayList<AbstractInsnNode>();for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()>=0)r.add(i);return r;}
 static boolean isInt(AbstractInsnNode i,int x){if(i==null)return false;int o=i.getOpcode();if(o>=ICONST_M1&&o<=ICONST_5)return o-ICONST_0==x;if(i instanceof IntInsnNode)return ((IntInsnNode)i).operand==x;return i instanceof LdcInsnNode&&Integer.valueOf(x).equals(((LdcInsnNode)i).cst);}
 static boolean rangeScale(MethodNode m,String base){List<AbstractInsnNode>x=real(m);for(int i=0;i+4<x.size();i++)if(x.get(i) instanceof FieldInsnNode&&x.get(i).getOpcode()==GETFIELD&&base.equals(((FieldInsnNode)x.get(i)).owner)&&"I".equals(((FieldInsnNode)x.get(i)).desc)&&isInt(x.get(i+1),3)&&x.get(i+2).getOpcode()==IMUL&&isInt(x.get(i+3),2)&&x.get(i+4).getOpcode()==IDIV)return true;return false;}
 static boolean callDistance(MethodNode m,String base){for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode){MethodInsnNode x=(MethodInsnNode)i;if(x.getOpcode()==INVOKESTATIC&&"(IIII)I".equals(x.desc)&&base.equals(x.owner))return true;}return false;}
 static boolean call(MethodNode m,String owner){for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode&&owner.equals(((MethodInsnNode)i).owner))return true;return false;}
 static boolean iterator(MethodNode m){int count=0;for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode){MethodInsnNode x=(MethodInsnNode)i;if("(I)Ljava/lang/Object;".equals(x.desc))count++;}return count>0;}
 public static void main(String[]a)throws Exception{JarFile j=new JarFile(a[0]);Map<String,ClassNode> cs=new LinkedHashMap<String,ClassNode>();Enumeration<JarEntry> e=j.entries();while(e.hasMoreElements()){JarEntry z=e.nextElement();if(z.getName().endsWith(".class")){ClassNode c=cn(rd(j.getInputStream(z)));cs.put(c.name,c);}}j.close();ClassNode cast=null;for(ClassNode c:cs.values()){boolean init=false,gate=false;for(MethodNode m:c.methods){Type[] args=Type.getArgumentTypes(m.desc);if((m.access&ACC_STATIC)==0&&Type.VOID_TYPE.equals(Type.getReturnType(m.desc))&&args.length==4&&args[0].getSort()==Type.OBJECT&&args[1].getSort()==Type.OBJECT&&args[2].getSort()==Type.INT&&args[3].getSort()==Type.BYTE)init=true;if("()Z".equals(m.desc))for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode&&"java/lang/System".equals(((MethodInsnNode)i).owner)&&"currentTimeMillis".equals(((MethodInsnNode)i).name))gate=true;}if(init&&gate){cast=c;break;}}if(cast==null)throw new Error("cast missing");MethodNode init=null;for(MethodNode m:cast.methods){Type[] t=Type.getArgumentTypes(m.desc);if((m.access&ACC_STATIC)==0&&Type.VOID_TYPE.equals(Type.getReturnType(m.desc))&&t.length==4&&t[0].getSort()==Type.OBJECT&&t[1].getSort()==Type.OBJECT&&t[2].getSort()==Type.INT&&t[3].getSort()==Type.BYTE)init=m;}String actor=Type.getArgumentTypes(init.desc)[0].getInternalName();System.out.println("CAST="+cast.name+" ACTOR="+actor+" INIT="+init.name+init.desc);for(ClassNode c:cs.values()){if(actor.equals(c.name)||actor.equals(c.superName)){System.out.println("ACTORCLASS="+c.name+" SUPER="+c.superName);for(MethodNode m:c.methods){if(rangeScale(m,actor)||callDistance(m,actor)||iterator(m)){System.out.println(" CANDIDATE="+m.name+m.desc+" n="+real(m).size()+" scale="+rangeScale(m,actor)+" dist="+callDistance(m,actor)+" iter="+iterator(m));}}}}
 for(ClassNode c:cs.values())if(cast.name.equals(c.name)){for(MethodNode m:c.methods){if("(I)V".equals(m.desc)){System.out.println("CAST_INT="+m.name+m.desc+" n="+real(m).size());int i=0;for(AbstractInsnNode x:m.instructions.toArray()){if(x.getOpcode()<0)continue;if(x instanceof MethodInsnNode){MethodInsnNode y=(MethodInsnNode)x;System.out.println("  "+i+" CALL "+y.owner+"."+y.name+y.desc);}else if(x instanceof JumpInsnNode){System.out.println("  "+i+" JUMP "+x.getOpcode()+" -> label");}i++;}}}}
 }
}
